    static let preposicaoRegendoPronome = "((?:^|[^0-9A-Za-zÀ-ÿ])((de|do|da|dos|das|com|pra|para|por|em|no|na|nos|nas|ao|aos|[àá]s?|sem|sobre|entre|at[ée]|of|for|with|to|about|by|from|con|sin|entre|hacia))\\s+([0-9A-Za-zÀ-ÿ_-]+\\s+){0,2}$)"
    /// GENITIVO DESCRITIVO: `remuneração da equipe` diz de quem o dinheiro é,
    /// não pra onde vai — e é o texto que o AgentTool ensina ao modelo. Ver
    /// `_porque_genitivo_descritivo`.
    static let genitivoDescritivo = "(?<![0-9A-Za-zÀ-ÿ])(gorjeta|gorjetas|caixinha|servi[çc]o|gratifica[çc][ãa]o|gratuity|tip|service charge|remunera[çc][ãa]o|sal[áa]rio|renda|verba|remuneration|wages?|salario|sueldo)(?![0-9A-Za-zÀ-ÿ])\\s+((?!(?:é|era|foi|são|eram|foram|tá|está|estão|estava|fica|ficam|ficou|vai|vão|tem|têm|tinha|há|pode|podem|deve|devem|quer|querem|sabe|sabem|paga|pagam|pagou|acerta|acertam|confirma|confirmam|chama|chamam|faz|fazem|fez|dá|dão|deu|recebe|recebem|recebeu|resolve|resolvem|precisa|precisam|leva|levam|entra|entram|mostra|mostram|distribui|distribuem|reparte|repartem|repassa|repassam|entrega|entregam|avisa|avisam|fala|falam|traz|trazem|manda|mandam|pede|pedem|pergunta|perguntam|cobra|cobram|junta|juntam|soma|somam|divide|dividem|acerto|acerta|va|van|es|son|queda|quedan|sale|salen|recibe|reciben|reparte|reparten|distribuye|distribuyen|cobra|cobran|paga|pagan|deja|dejan|go|goes|went|keep|keeps|kept|get|gets|got|take|takes|took|is|are|was|were|has|have|can|will|does|did|goes|keeps|pays|knows|works|takes|es|son|están|puede|pueden|saben|pagan|queda|quedan)(?![0-9A-Za-zÀ-ÿ]))[0-9A-Za-zÀ-ÿ_-]+\\s+){0,2}(de\\s+la|d[eoa]s?|del|of\\s+the)\\s+((?:o|a|os|as|the|el|la|los|las|um|uma)\\s+)?([0-9A-Za-zÀ-ÿ_-]+\\s+){0,2}(equipe|equipo|\\bstaff\\b|\\bteam\\b|gar[çc]o[nm]s?|gar[çc]onete|atendente|el personal|\\bpersonal\\b|sal[ãa]o|funcion[áa]ri|colaborador|mozo|moza|barman|bartender|cozinha|copa|camarer[oa]s?|meser[oa]s?|ma[îi]tre|sommelier|cumim|waiters?|\\bmo[çc]o|\\bmo[çc]a|servers?|\\btimes?\\b|quem\\s+([0-9A-Za-zÀ-ÿ_-]+\\s+){0,2}(te\\s+)?([0-9A-Za-zÀ-ÿ_-]+\\s+){0,2}(serve|serviu|atende|atendeu))"
    /// Enumeração com a POLARIDADE do lado certo: verbo que a lista não
    /// conhece vira recusa, nunca escape. Ver `_porque_predicacao`.
    static let verboFinito = "(?:^|[^0-9A-Za-zÀ-ÿ])(é|era|foi|são|eram|foram|tá|está|estão|estava|fica|ficam|ficou|vai|vão|tem|têm|tinha|há|pode|podem|deve|devem|quer|querem|sabe|sabem|paga|pagam|pagou|acerta|acertam|confirma|confirmam|chama|chamam|faz|fazem|fez|dá|dão|deu|recebe|recebem|recebeu|resolve|resolvem|precisa|precisam|leva|levam|entra|entram|mostra|mostram|distribui|distribuem|reparte|repartem|repassa|repassam|entrega|entregam|avisa|avisam|fala|falam|traz|trazem|manda|mandam|pede|pedem|pergunta|perguntam|cobra|cobram|junta|juntam|soma|somam|divide|dividem|acerto|acerta|va|van|es|son|queda|quedan|sale|salen|recibe|reciben|reparte|reparten|distribuye|distribuyen|cobra|cobran|paga|pagan|deja|dejan|go|goes|went|keep|keeps|kept|get|gets|got|take|takes|took|is|are|was|were|has|have|can|will|does|did|goes|keeps|pays|knows|works|takes|es|son|están|puede|pueden|saben|pagan|queda|quedan)(?=[^0-9A-Za-zÀ-ÿ]|$)"
    /// Relativa, retirada antes do teste de predicação.
    static let relativaQualquer = "(?:^|[^0-9A-Za-zÀ-ÿ])(que|quem|who|whom|that|qui[eé]n(?:es)?)\\s+([0-9A-Za-zÀ-ÿ_-]+\\s+){0,2}((?:me|te|se|lhe|nos|le|you)\\s+)?([0-9A-Za-zÀ-ÿ_-]+\\s+){0,2}[0-9A-Za-zÀ-ÿ_-]+"
    static let marcadorDeLista = "^\\s*[-*•+>]\\s*"
    static let separadorInterno = "(?<!\\d),(?!\\d)|\\b(mas|por[ée]m|e sim|but|pero|sino)\\b"
    /// Ponto entre DÍGITOS não fecha oração: `R$ 1.250,00` é um número.
    /// Ver `_porque_separador_de_oracao`.
    static let separadorDeOracao = "(?<!\\d)\\.|\\.(?!\\d)|[;!?:\\n—]"
    /// Separa ESCOPO de cláusula, e inclui a conjunção coordenativa.
    static let separadorDeClausula = "(?<!\\d),(?!\\d)|\\b(e sim|e|mas|por[ée]m|ou|and|but|or|\\by\\b|pero|sino)\\b|;"
    /// Abertura de cláusula ADVERSATIVA: ela QUALIFICA a oração anterior em
    /// vez de afirmar coisa nova. Com slot de advérbio, porque o fabricador
    /// derrubou as três variantes de `— sempre mas não pela folha`.
    static let adversativaInicial = "^\\s*((?:([0-9A-Za-zÀ-ÿ_]+mente|assim|sempre|hoje|logo|j[áa]|ainda|mesmo|s[óo]|always|still|already|only|just|siempre|ya|todav[íi]a|a[úu]n|solo))\\s+)*(mas|por[ée]m|e sim|but|pero)(?![0-9A-Za-zÀ-ÿ])"
    /// Negador COLADO no destinatário. Sem o `sem`: ver `_porque_negadores`.
    static let negadorColado = "^\\s*((?:([0-9A-Za-zÀ-ÿ_]+mente|assim|sempre|hoje|logo|j[áa]|ainda|mesmo|s[óo]|always|still|already|only|just|siempre|ya|todav[íi]a|a[úu]n|solo))\\s+)*(que\\s+)?(n[ãa]o|nunca|nem|jamais|not|never|jam[áa]s|ni)\\b"
    /// A frase que o produto diz. Não é uma variação.
    static let sancionada = "o restaurante distribui à equipe, como manda a lei"
}
